import{_ as e,o as t,c as s,a2 as i}from"./chunks/framework.Dj7FWXx_.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1789564099000}'),l={name:"guide/getting-started.md"};function n(p,a,o,d,h,r){return t(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><h2 id="_1-下载正式包" tabindex="-1">1. 下载正式包 <a class="header-anchor" href="#_1-下载正式包" aria-label="Permalink to &quot;1. 下载正式包&quot;">​</a></h2><p>打开<a href="/releases/">下载中心</a>，按系统和 CPU 架构下载对应正式版压缩包。</p><p>下载后建议使用同一发布页中的 <code>SHA256SUMS.txt</code> 校验文件完整性。</p><h2 id="_2-解压并启动" tabindex="-1">2. 解压并启动 <a class="header-anchor" href="#_2-解压并启动" aria-label="Permalink to &quot;2. 解压并启动&quot;">​</a></h2><p>Windows：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">mengka-nt.exe</span></span></code></pre></div><p>Linux：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./mengka-nt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./mengka-nt</span></span></code></pre></div><p>首次启动时，终端会显示 Web 安装地址。打开该地址，阅读使用协议，并按向导设置监听端口以及本机管理员账号、密码。管理员凭据只保存在当前框架的本地数据库中，不依赖官网用户体系。</p><div class="warning custom-block"><p class="custom-block-title">从旧版官网管理员迁移</p><p>如果页面检测到旧版官网管理员，请先在服务器设置 <code>MENGKA_ALLOW_LOCAL_ADMIN_MIGRATION=1</code> 并重启，再创建本地管理员。确认新账号可以登录后，移除该环境变量并再次重启。迁移只替换管理员身份，不会删除 QQ 账号、插件、节点或运行数据。</p></div><h2 id="_3-准备账号环境" tabindex="-1">3. 准备账号环境 <a class="header-anchor" href="#_3-准备账号环境" aria-label="Permalink to &quot;3. 准备账号环境&quot;">​</a></h2><p>进入 WebUI 后按下面顺序操作：</p><ol><li>在“节点”中检查或添加连接节点；</li><li>在“指纹”中创建账号使用的设备指纹；</li><li>在“账号”中添加 QQ，并选择协议、指纹和节点；</li><li>发起登录，按页面提示完成滑块、短信或其他安全验证；</li><li>登录成功后检查账号在线状态和运行日志。</li></ol><h2 id="_4-接入插件" tabindex="-1">4. 接入插件 <a class="header-anchor" href="#_4-接入插件" aria-label="Permalink to &quot;4. 接入插件&quot;">​</a></h2><p>在“插件”中创建服务，选择正向或反向 WebSocket，妥善保存服务令牌。不要把令牌写入公开源码、前端代码或 URL。</p><p><a href="/development/">继续阅读插件开发 →</a></p>`,17)])])}const g=e(l,[["render",n]]);export{k as __pageData,g as default};
